SELECT ?ed ?start (COUNT(DISTINCT ?country) AS ?hosts) (GROUP_CONCAT(DISTINCT STR(?n); SEPARATOR="|") AS ?participants) (GROUP_CONCAT(DISTINCT ?official; SEPARATOR="|") AS ?officialNames) WHERE {
  VALUES ?series { wd:Q19317 wd:Q19323 }
  ?ed wdt:P3450 ?series ; wdt:P580 ?start ; wdt:P1346 ?winner .
  FILTER(YEAR(?start) >= 1930 && YEAR(?start) <= 2026)
  OPTIONAL { ?ed wdt:P17 ?country }
  OPTIONAL { ?ed wdt:P1132 ?n }
  OPTIONAL { ?ed wdt:P1448 ?official }
} GROUP BY ?ed ?start ORDER BY ?start

SELECT ?item ?kind ?lang ?text WHERE {
  VALUES ?item { wd:Q713750 wd:Q43310 }
  { ?item rdfs:label ?text BIND("label" AS ?kind) } UNION { ?item skos:altLabel ?text BIND("alias" AS ?kind) }
  BIND(LANG(?text) AS ?lang)
  FILTER(?lang IN ("en", "sv", "mul"))
}

SELECT ?s ?sLabel ?p ?o ?oLabel WHERE {
  { ?s ?p wd:Q500308 . BIND(wd:Q500308 AS ?o) }
  UNION
  { VALUES ?s { wd:Q500308 } ?s ?p ?o . FILTER(?o IN (wd:Q148, wd:Q103177, wd:Q850876)) }
  UNION
  { VALUES ?s { wd:Q500308 } ?s ?pp ?st . ?st ?p ?o . FILTER(STRSTARTS(STR(?p), "http://www.wikidata.org/prop/qualifier/")) }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

